<div id="supplier-modal" class="modal"><div class="modal-panel"><div class="modal-head"><h2 id="modal-title">Tambah Supplier</h2><button class="modal-close" type="button" onclick="tutupModal()">&times;</button></div><form id="supplier-form" method="POST" action="{{ route('admin.supplier.store') }}">@csrf<input id="method-field" type="hidden" name="_method" value="POST"><div class="form-field"><label for="nama">Nama Supplier</label><input id="nama" name="nama" maxlength="120" required></div><div class="form-field"><label for="kontak">Kontak</label><input id="kontak" name="kontak" maxlength="50" placeholder="Telepon atau WhatsApp"></div><div class="form-field"><label for="alamat">Alamat</label><textarea id="alamat" name="alamat"></textarea></div><div class="form-field"><label for="catatan">Catatan</label><input id="catatan" name="catatan" maxlength="255"></div><button class="btn-primary modal-submit" type="submit">Simpan Supplier</button></form></div></div>
<script>const modal=document.getElementById('supplier-modal'),form=document.getElementById('supplier-form');function bukaModal(id=null,nama='',kontak='',alamat='',catatan=''){document.getElementById('modal-title').textContent=id?'Edit Supplier':'Tambah Supplier';form.action=id?'{{ url('/admin/supplier') }}/'+id:'{{ route('admin.supplier.store') }}';document.getElementById('method-field').value=id?'PUT':'POST';document.getElementById('nama').value=nama;document.getElementById('kontak').value=kontak;document.getElementById('alamat').value=alamat||'';document.getElementById('catatan').value=catatan;modal.classList.add('open');document.getElementById('nama').focus()}function tutupModal(){modal.classList.remove('open')}modal.addEventListener('click',e=>{if(e.target===modal)tutupModal()});</script>
